with filtered_web_events as (select * from web_events where event_type in ('page_view', 'click', 'add_to_cart') and page = '/checkout' and to_date(event_time) < '2023-03-01'), Summary as (select to_date(event_time) as event_day, session_id, count(*) as row_count from filtered_web_events group by to_date(event_time), session_id) select event_day, session_id, row_count from Summary order by row_count desc;
